import{_ as o,o as t,c as r,a2 as e}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"正传历史","description":"","frontmatter":{},"headers":[],"relativePath":"中层/历史/正传历史.md","filePath":"中层/历史/正传历史.md","lastUpdated":1787065118000}'),l={name:"中层/历史/正传历史.md"};function n(s,a,h,i,u,q){return t(),r("div",null,[...a[0]||(a[0]=[e('<h1 id="正传历史" tabindex="-1">正传历史 <a class="header-anchor" href="#正传历史" aria-label="Permalink to &quot;正传历史&quot;">​</a></h1><blockquote><p>中层视角的福瑞时代真实编年史：从前传落幕、共同体建立，到当前鹿熊冷战时代，表层历史之下的真实脉络。表层版本见 <a href="./../../表层/历史/共同体时期" class="layer-link" data-layer="表层">共同体时期</a>、<a href="./../../表层/历史/黑暗时代" class="layer-link" data-layer="表层">黑暗时代</a>、<a href="./../../表层/历史/当前时代" class="layer-link" data-layer="表层">当前时代</a>。</p></blockquote><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>前传决战落幕、林月于共同体建立初期离世后，神机在间章登神并布局新世界（详见 <a href="./间章历史">间章历史</a>），福瑞时代由此开启。正传历史以中层视角记录这一时代：共同体的建立与覆灭、地脉灾难、黑暗时代、太空支线、狮族战争，直至当前鹿熊冷战的格局。许多表层历史事件背后是神机与维斯塔的谋划、基底层的干涉与神权的运作。</p><h2 id="一、共同体建立与真相" tabindex="-1">一、共同体建立与真相 <a class="header-anchor" href="#一、共同体建立与真相" aria-label="Permalink to &quot;一、共同体建立与真相&quot;">​</a></h2><p><strong>事件脉络</strong>：神明红星（维斯塔）带领福瑞智慧生灵脱离蒙昧、步入文明，建立&quot;共同体&quot;，赋予各族同一身份——&quot;共同体公民&quot;；梯形神殿建成，神明投影系统启用。五大主族按特质分工：牛族负责农业、鹿族负责科研、熊族负责工业、鹤族负责政治、甲族负责军事。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../../表层/历史/共同体时期" class="layer-link" data-layer="表层">共同体时期</a></p></blockquote><p><strong>真相</strong>：共同体的建立与覆灭均为神机计划的一部分——神机对维斯塔说&quot;建一个国家，把物种统筹起来，让故事走起来&quot;。维斯塔无法完全隔离人格、必然会入戏，而这恰恰是计划所需：故事若显得虚假，就会产生暗线，而神机不想让故事有暗线。维斯塔是全心投入的，他真的把所有人都算进去了，包括他自己。共同体覆灭同样是计划的一部分：神机需要绝对的坏事（如黑暗时代）来为毁灭神的出现打基础，保证其出现是可控的。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../世界/神机谋划">神机谋划</a></p></blockquote><h2 id="二、地脉灾难与神明退场真相" tabindex="-1">二、地脉灾难与神明退场真相 <a class="header-anchor" href="#二、地脉灾难与神明退场真相" aria-label="Permalink to &quot;二、地脉灾难与神明退场真相&quot;">​</a></h2><p><strong>事件脉络</strong>：建国171年，地脉异常开始——光芒亮度明显增加、逐渐有了宽度，地表出现数毫米到数厘米不定的高低差。神明曾被金色光柱带离、不到一个下午便返回，面色凝重。年末，神明召集甲族将领，告知灾难即将降临，甲族作为最后的防线。最终地脉毫无征兆地爆发涌动，主要力量直奔神明，甲族拼尽全力拦截余波，神明本体被地脉吞没、暂时失去意识。此前的执政权力移交使鹤族陷入威信不足、决策瘫痪的困境，为共同体崩溃埋下伏笔。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../../表层/历史/共同体时期" class="layer-link" data-layer="表层">共同体时期</a></p></blockquote><p><strong>真相</strong>：地脉危机并非自然灾难，而是<strong>基底层的扭曲人类</strong>（前传BOSS送入基底层、被逐渐扭曲同化的虚拟人类）试图通过地球被撕裂的薄弱点强行突破回现实宇宙——其高维力量冲击现实，形成了地脉危机；北美与喜马拉雅作为地脉源头承受最大冲击，但二者并非冲击目标。维斯塔在此次危机中被地脉吞没，许下修复地脉的宏愿，本质是用神权压制基底层的突破、缝合地球被撕裂的薄弱点；神机随即使用上位创造神权立下新规则&quot;<strong>下位神权无法修改编辑基底层</strong>&quot;，维斯塔的宏愿&quot;卡上BUG&quot;进入悖论状态。宏愿的庞大变化权柄附着于每一道地脉，虽无法压回修复，却将地脉彻底围住、使其生长减缓甚至静止，这些附着变化权柄的地脉成为&quot;魔力&quot;的来源。宏愿代价触发神权继承流程，拉斯塔作为下一代载体卡在新生阶段，形成&quot;维斯塔卡死亡 + 拉斯塔卡新生&quot;的双载体悖论。宏愿力量令维斯塔大脑宕机，起初连接着神殿本可缓慢恢复，但鹿族心急发起&quot;复活神明计划&quot;，令神殿与神明彻底断联；此后地脉大肆扩展。约黑暗时代百年，在神机指示下的狐族少女将破败神殿与神明重新连接（外接算力远强于维斯塔自身），才勉强唤醒维斯塔，此后其暂留神殿压制地脉。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../世界/地脉与魔法">地脉与魔法</a></p></blockquote><h2 id="三、共同体崩溃与黑暗时代真相" tabindex="-1">三、共同体崩溃与黑暗时代真相 <a class="header-anchor" href="#三、共同体崩溃与黑暗时代真相" aria-label="Permalink to &quot;三、共同体崩溃与黑暗时代真相&quot;">​</a></h2><h3 id="鹿族-神明复活计划-事故" tabindex="-1">鹿族&quot;神明复活计划&quot;事故 <a class="header-anchor" href="#鹿族-神明复活计划-事故" aria-label="Permalink to &quot;鹿族&quot;神明复活计划&quot;事故&quot;">​</a></h3><p>鹤族公信力不足，鹿族作为主族之首独揽大权，举国主导&quot;神明复活计划&quot;，实验却发生严重事故：以神明躯体为中心的地脉能量瞬间暴走，神殿被炸翻，首都区域地面严重下沉，河水涌入，繁华的旧都数日内沦为<strong>水下之城</strong>。此事故引发第二次地脉灾难，甲族损失惨重，共同体基础设施几近崩断。</p><h3 id="甲族灭绝真相" tabindex="-1">甲族灭绝真相 <a class="header-anchor" href="#甲族灭绝真相" aria-label="Permalink to &quot;甲族灭绝真相&quot;">​</a></h3><p>失去神明后共同体暴露执政漏洞，民生与社会问题频发。鹰族通过多种舆论手段点燃民众对甲族的排异情绪，使甲族成为社会问题的替罪羊；鹿、熊、牛三族上层缺乏政治经验、受舆论裹挟，&quot;顺应民意&quot;联合围剿甲族。甲族因不愿对平民动武，被围困城中、断水断粮数月，最终因食用同类导致朊病毒爆发，幸存者屈指可数，幸存者遁入山林。其中一位幸存者被维斯塔所救（可能出于愧疚），长期在红星孤儿院做客，不知院长就是维斯塔。</p><h3 id="法师时代降临与黑暗时代开启" tabindex="-1">法师时代降临与黑暗时代开启 <a class="header-anchor" href="#法师时代降临与黑暗时代开启" aria-label="Permalink to &quot;法师时代降临与黑暗时代开启&quot;">​</a></h3><p>地脉灾难后常有超自然个体出现，被称为法师，超自然力量被称为魔法；法师数量逐渐增多形成法师阶级，共同体渐渐名存实亡。约建国200年后，鹰族代表宣布共同体解体，分裂为数个法师封地，黑暗时代正式开启；猪、蝠、豹、虎四族与鹰族合并组成新五族统治。黑暗时代的整个框架体系由鹰族搭建——强者为尊、贵族世袭等规则均为鹰族定下；奴隶制渐渐形成，牛族成为第一个彻底沦为奴隶的种族，鹿族逐渐沦为法师的助手/宠物。</p><p><strong>法师食人史真相</strong>：魔法的本质是变化神权的神力溢散，其与疾病的因果关系实际相反——并非魔法导致疾病，而是疾病发生使身体产生更多变化、吸引更多神力附着，法力随之增强；唯有食用智慧种族的新鲜血肉才能产生&quot;变化中和效应&quot;、暂时稳定身体状态，由此形成恶性循环，开启了贯穿黑暗时代的法师食人史。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../世界/地脉与魔法">地脉与魔法</a></p></blockquote><h3 id="狼族少年登神-约黑暗时代180年" tabindex="-1">狼族少年登神（约黑暗时代180年） <a class="header-anchor" href="#狼族少年登神-约黑暗时代180年" aria-label="Permalink to &quot;狼族少年登神（约黑暗时代180年）&quot;">​</a></h3><p>无父无母的狼族孤儿被南方狼村收养，度过十年幸福生活，后被猪族奴隶官抓走，亲友在其面前屈辱惨死。仇恨点燃&quot;魔力&quot;（实为毁灭神力）初步觉醒，他屠戮奴隶厂解放狼族、建立初步国家；遭猪族法师绞杀后拼死反击并与新五族签订和平条例，却遭猪、虎、豹、蝠四族联合背刺，狼族死伤惨重。少年彻底失去幻想，仇恨激活本质彻底登神，随后独自巡游大地四方，数年内灭绝四族，在即将灭绝鹰族时突然消失。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../人物/狼族少年">狼族少年</a></p></blockquote><h3 id="狐族奴隶牺牲与唤醒神明-约黑暗时代100年" tabindex="-1">狐族奴隶牺牲与唤醒神明（约黑暗时代100年） <a class="header-anchor" href="#狐族奴隶牺牲与唤醒神明-约黑暗时代100年" aria-label="Permalink to &quot;狐族奴隶牺牲与唤醒神明（约黑暗时代100年）&quot;">​</a></h3><p>一位天生可以排斥地脉的特殊狐族奴隶燃烧生命，在&quot;那位神明&quot;——实为二代创造神神机——的指示下前往旧都水下神殿，顶着极端环境将破败神殿与神明重新连接，以自身性命唤醒昏迷已久的神明（维斯塔），却迎来了出乎意料的结局。</p><h3 id="鹿族暗中崛起真相" tabindex="-1">鹿族暗中崛起真相 <a class="header-anchor" href="#鹿族暗中崛起真相" aria-label="Permalink to &quot;鹿族暗中崛起真相&quot;">​</a></h3><p>鹿族利用<strong>梯形神殿遗留技术</strong>与魔法结合，开发出精神控制能力——使用者须忍受&quot;颅内炸裂的噪音&quot;，对法师与奴隶官进行一对一长期精神控制，成为幕后的实际掌权者。首位成功运用者为特殊体质的塞林（控制一个法师几乎无不适，此前&quot;不是没人想到，是只有他能做到&quot;）；控制多个目标时噪音呈指数级增长。鹿族明面上的革命仅是&quot;丢掉被控制的法师后顺势走向台面的过场&quot;，其暗中崛起的历史被彻底隐藏。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../世界/特殊地点">特殊地点</a></p></blockquote><h3 id="黑暗时代结束-约200年" tabindex="-1">黑暗时代结束（约200年） <a class="header-anchor" href="#黑暗时代结束-约200年" aria-label="Permalink to &quot;黑暗时代结束（约200年）&quot;">​</a></h3><p>新五族掌权彻底消失，狐族在狼族庇佑下建立城邦，其余种族逐渐走向独立。</p><h2 id="四、太空支线" tabindex="-1">四、太空支线 <a class="header-anchor" href="#四、太空支线" aria-label="Permalink to &quot;四、太空支线&quot;">​</a></h2><p><strong>清除地外智慧物种</strong>：为防止毁灭神在其他星系出现，神机与维斯塔做出清除所有地外智慧物种的决定——创造太空武器与太空文明交战，大部分直接灭绝，只留数据存档。</p><p><strong>天穹破碎事件真相</strong>（建国22年）：并非天灾，而是<strong>神机与外星文明的太阳系大战</strong>。掌握超距作用技术的外星文明入侵太阳系，从冥王星一路打到地球轨道；神机以创造神权急速进步和反击，最终在地月系击退入侵者。战斗中一艘外星飞船坠毁，撞上神机为掩饰自己改造太阳系动作而制造的<strong>天幕</strong>，形成&quot;天穹破碎&quot;事件；坠毁飞船上的外星种族——<strong>焰种</strong>（接触氧气即自燃，因死亡时燃烧被贬称）——短暂出现后，残部被神机的精灵部队搜查猎杀殆尽。神环亦在此事件中首次清晰显现。</p><p><strong>银河之眼</strong>：神机在银河中心超大黑洞处建造的超级机器，可对银河系进行夸克级监控乃至反向控制（如时间暂停）；其部件包含悖论科技，需神机本人在场用神权驱动，神机几乎不用它。</p><p><strong>月球武器平台</strong>：月球被改造为巨大的<strong>对基底层特化武器平台</strong>，内部几乎无自然地壳结构，满是高强度材料构成的支撑结构与武器系统；炮口常对准地球（尤其已炸裂、漂浮的北美洲），一旦地脉有失控风险便以融合超距作用原理的光束持续压制，也可用于修补宇宙空间缝隙。</p><p><strong>北美洲炸裂</strong>：前传决战中能量炮虽被击偏仍贯穿地球，摧毁了北美洲与大半喜马拉雅；北美洲已彻底炸裂、处于漂浮状态，成为月球平台的重点压制区域。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../世界/太空清除计划">太空清除计划</a>、<a href="./../世界/太空巨构">太空巨构</a></p></blockquote><h2 id="五、狮族战争真相" tabindex="-1">五、狮族战争真相 <a class="header-anchor" href="#五、狮族战争真相" aria-label="Permalink to &quot;五、狮族战争真相&quot;">​</a></h2><p><strong>六边形沙漠的本质</strong>：狮族占据的六边形沙漠并非自然地貌，而是<strong>天穹破碎事件中掉落的天穹碎块</strong>——六边形是神机所造人工天幕的原生几何结构。其能量管线出现错误泄露，高能能量持续释放，导致沙漠近百年持续升温、最终成为无人区，狮族面临种族存续危机。<strong>狮族战力根源</strong>：泄露的高能能量浸入附近岩石层形成橙黄色高能结晶（磨粉为极高能炸药、整块为极高能燃料）；撞在天幕上的外星飞船残骸留存于沙漠，带来异域科技，使小族狮族拥有了抗衡鹿熊的实力。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../世界/太空巨构">太空巨构</a></p></blockquote><p><strong>战争性质</strong>：黑暗时代结束后大陆第一次真正意义上的大规模热武器战争，双方热武器体系均不成熟，惨烈程度堪比&quot;凡尔登绞肉机&quot;。狮族侵略部队以仆从族（豺族等）为主在前线与鹿族绞肉，本族主力在北线与熊族进行重武装步兵、精英装甲战斗。</p><p><strong>古斯塔夫救下拉斯塔</strong>：狮族战争中，拉斯塔的村子被仆从族屠戮，被豺族追兵追捕时被&quot;没有尾巴的巨龙&quot;吓走追兵——该&quot;巨龙&quot;实为<strong>古斯塔夫</strong>（智能空中战斗平台），当时正运载鹿族&quot;环形山计划&quot;核弹前往狮族首都，救她是执行任务途中的偶然。这成为拉斯塔&quot;寻找龙&quot;执念的根源。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../世界/龙族真相">龙族真相</a>、<a href="./../人物/古斯塔夫">古斯塔夫</a></p></blockquote><p><strong>狮族终局</strong>：古斯塔夫运载的核弹直指狮族首都，首都陷落、行政机构瘫痪；鹿熊趁机反击，狮族单方面投降却不被鹿族高层认可（受狼族屠杀立国行为影响与战争仇恨延续），直至&quot;向平民进攻&quot;的命令引发舆论风波后战争才刹住。狮族十不存一，幸存者几乎都是老弱病残，主权与科技被鹿熊瓜分，领地继续升温无法生存，政府流亡成为仅在地图上存在的国家。</p><p><strong>战争影响</strong>：鹿族损失大量法师与陆军精锐，催生厌战思潮与松散的国家体制；熊族磨合装甲部队、形成压倒性陆军优势，修正主义加剧；狼族认清工业化热武器的威力，转而积极发展热武器与核武器，成为冷战中具备军备实力的平衡者；鹿熊被迫联合平息战争后失去共同大敌、猜忌加剧，<strong>直接促成鹿熊冷战的正式形成</strong>。</p><h2 id="六、世界树的毁灭" tabindex="-1">六、世界树的毁灭 <a class="header-anchor" href="#六、世界树的毁灭" aria-label="Permalink to &quot;六、世界树的毁灭&quot;">​</a></h2><p>神机在喜马拉雅山附近建造了<strong>世界树</strong>——超大计算机中枢、信息收集中枢，精灵族是其意识节点（意识共通）。地脉灾难把世界树干断，导致精灵族共同网络断掉，精灵族从集体意识变为个体思维。神机未重建的原因：她知道修了还会断，而且断的时候肯定有更大的故事、波及更多事情，于是转而用银河之眼等替代方案监控。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../世界/特殊地点">特殊地点</a>、<a href="./../世界/神机谋划">神机谋划</a></p></blockquote><h2 id="七、当前时间线格局" tabindex="-1">七、当前时间线格局 <a class="header-anchor" href="#七、当前时间线格局" aria-label="Permalink to &quot;七、当前时间线格局&quot;">​</a></h2><p><strong>主角团现状</strong>：主角（失忆毁灭神）、维斯塔、拉斯塔均处于红星孤儿院；克隆仓库仍在太空运转，毁灭神权被持续稀释。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../世界/神机谋划">神机谋划</a>、<a href="./../世界/太空巨构">太空巨构</a></p></blockquote><p><strong>前传与正传的延续</strong>：从前传活到正传的角色不止维斯塔和神机，还有一些其余不怎么活跃的存在（如智能空中战斗平台古斯塔夫）。</p><p><strong>叙事博弈的起源</strong>：初代变化神最早发现这个世界不是那么讲逻辑，将这一认知传给奥克尔；奥克尔尝试利用叙事逻辑；神机从前传中学习到这一点，并成为最深入的实践者。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../../底层/规则/叙事与玩家" class="layer-link" data-layer="底层">叙事与玩家</a></p></blockquote><h2 id="八、主线叙事与多线结局" tabindex="-1">八、主线叙事与多线结局 <a class="header-anchor" href="#八、主线叙事与多线结局" aria-label="Permalink to &quot;八、主线叙事与多线结局&quot;">​</a></h2><h3 id="主线起点与双线选择" tabindex="-1">主线起点与双线选择 <a class="header-anchor" href="#主线起点与双线选择" aria-label="Permalink to &quot;主线起点与双线选择&quot;">​</a></h3><p>主角（狼族少年）从位于狼国境内的红星孤儿院出发，面临两条主要剧情线路的选择。失忆主角身份特殊、涉及神机计划，神机自有办法让狼国官方不察觉其真实身份。通常情况下，<strong>第一周目无法直接选择熊国线</strong>，需要先完成鹿国线后才能解锁。</p><h3 id="鹿国线" tabindex="-1">鹿国线 <a class="header-anchor" href="#鹿国线" aria-label="Permalink to &quot;鹿国线&quot;">​</a></h3><p>核心任务是前往鹿国接受其支持，帮助鹿国解决体制过度分散、制度缺陷内耗与熊国军事压力等问题。关键角色是一位看起来平平无奇的鹿族高层（<strong>龙鹿</strong>）。主角帮助鹿国整合力量、优化制度，最终在正面战场或代理人战争中击败熊国，大陆恢复和平。此线中龙鹿内心的灭世执念被化解，放弃寻找上位毁灭神权，成为和平的关键一环。</p><h3 id="熊国线" tabindex="-1">熊国线 <a class="header-anchor" href="#熊国线" aria-label="Permalink to &quot;熊国线&quot;">​</a></h3><p>核心任务是帮助熊国整顿极端集中化的僵化与独裁、修正主义倾向、化解对鹿国等的仇恨。同一位龙鹿在此线中未能被感化：他通过秘密的生物研究为自己<strong>重塑了龙躯</strong>、变回真龙，并<strong>继承了上位毁灭神权</strong>，开始灭世进程。熊国需一边对抗龙鹿、一边保护鹿国平民。上位毁灭神权本应极度危险，但其真正力量已被<strong>神机与维斯塔联手压制</strong>，留给主角一个&quot;可控&quot;的危机；神与神机不亲自解决，表层原因是主角拥有毁灭神权，真相则是叙事逻辑的约束——此事必须由主角解决，才能真正&quot;了结&quot;。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../人物/龙鹿">龙鹿</a>、<a href="./../../底层/人物/上位毁灭神" class="layer-link" data-layer="底层">上位毁灭神</a></p></blockquote><h3 id="狼族线-真结局" tabindex="-1">狼族线（真结局） <a class="header-anchor" href="#狼族线-真结局" aria-label="Permalink to &quot;狼族线（真结局）&quot;">​</a></h3><p>完成鹿国线和熊国线后解锁。主角在两条线路的经验基础上，先人一步在狼族地盘上<strong>找到了上位毁灭神权的本源</strong>，开启新的历程。真结局中，玩家将真正接触到神机，了解太空、银河之眼、世界树、月球的真相以及整个世界最深层的秘密，并面临最终选择：是否使用<strong>上位毁灭神权</strong>删除&quot;<strong>叙事逻辑</strong>&quot;本身。</p><h3 id="删除叙事逻辑-的深层含义" tabindex="-1">&quot;删除叙事逻辑&quot;的深层含义 <a class="header-anchor" href="#删除叙事逻辑-的深层含义" aria-label="Permalink to &quot;&quot;删除叙事逻辑&quot;的深层含义&quot;">​</a></h3><p>该选择直接作用于世界的顶层架构。删除后，玩家（作为叙事存在的具象化）将不复存在，世界不再有&quot;主角&quot;&quot;剧情&quot;&quot;伏笔&quot;等概念，一切都将遵循纯粹的物理、因果与现实逻辑——这是一个&quot;故事终结&quot;的结局，也是角色们获得真正&quot;自由&quot;的可能。拒绝删除，则世界继续在叙事逻辑的框架下运行，故事继续、支线延续。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../../底层/规则/叙事与玩家" class="layer-link" data-layer="底层">叙事与玩家</a>、<a href="./../../底层/规则/神权体系" class="layer-link" data-layer="底层">神权体系</a></p></blockquote><h2 id="人类概念的传闻" tabindex="-1">人类概念的传闻 <a class="header-anchor" href="#人类概念的传闻" aria-label="Permalink to &quot;人类概念的传闻&quot;">​</a></h2><p>当前世界的智慧福瑞生灵均被纳入&quot;人类&quot;的统一称呼范畴，&quot;人&quot;指拥有高级思考能力与复杂感情、可双足直立行走的生灵；此概念由神明赋予，并按外貌特征加前缀（鹿人、熊人等），打破了种族隔阂。尽管曾有传闻说&quot;人类&quot;其实是一种特殊物种的专属形容词，但大陆上的生灵始终没有找到那传说中的身影。</p><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./前传超算纪元">前传超算纪元</a></li><li><a href="./前传历史">前传历史</a></li><li><a href="./间章历史">间章历史</a></li><li><a href="./../../表层/历史/共同体时期" class="layer-link" data-layer="表层">共同体时期</a></li><li><a href="./../../表层/历史/黑暗时代" class="layer-link" data-layer="表层">黑暗时代</a></li><li><a href="./../../表层/历史/当前时代" class="layer-link" data-layer="表层">当前时代</a></li><li><a href="./../世界/神机谋划">神机谋划</a></li><li><a href="./../世界/地脉与魔法">地脉与魔法</a></li><li><a href="./../世界/太空巨构">太空巨构</a></li><li><a href="./../世界/太空清除计划">太空清除计划</a></li><li><a href="./../世界/特殊地点">特殊地点</a></li><li><a href="./../世界/龙族真相">龙族真相</a></li><li><a href="./../世界/历代三神">历代三神</a></li><li><a href="./../../底层/规则/叙事与玩家" class="layer-link" data-layer="底层">叙事与玩家</a></li><li><a href="./../../底层/规则/神权体系" class="layer-link" data-layer="底层">神权体系</a></li><li><a href="./../人物/维斯塔">维斯塔</a></li><li><a href="./../人物/神机">神机</a></li><li><a href="./../人物/拉斯塔">拉斯塔</a></li><li><a href="./../人物/狼族少年">狼族少年</a></li><li><a href="./../人物/龙鹿">龙鹿</a></li><li><a href="./../人物/古斯塔夫">古斯塔夫</a></li></ul>',75)])])}const c=o(l,[["render",n]]);export{g as __pageData,c as default};
